function RenameForm({ id }: { id: string }) {
  const [error, setError] = useState<string | null>(null);

  async function action(_prev: State, formData: FormData) {
    const name = formData.get("name") as string;
    const res = await rename(id, name);
    if (!res.ok) {
      setError(res.message);          // (A)
      return { ok: false };
    }
    return { ok: true };
  }

  const [state, formAction, isPending] = useActionState(action, { ok: true });

  return (
    <form action={formAction}>
      <input name="name" defaultValue="" />
      {error && <p role="alert">{error}</p>}
      <SubmitButton />
    </form>
  );
}

function SubmitButton() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>Save</button>;   // (B)
}
